const documentBase64='';
export async function residenceOrganizationDocument(request:Request,owner:(r:Request)=>Promise<boolean>){
 const headers={'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'};
 if(request.method!=='GET')return new Response('Método no permitido.',{status:405,headers:{...headers,Allow:'GET'}});
 if(!await owner(request))return new Response('Sesión no autorizada.',{status:401,headers});
 const bytes=Uint8Array.from(atob(documentBase64),c=>c.charCodeAt(0));
 return new Response(bytes,{headers:{...headers,'Content-Type':'application/pdf','Content-Disposition':'attachment; filename="Horario_Psicologia_Residencia_Carolina_Sanchez.pdf"'}});
}
